class Solution {
    public int maximumElementAfterDecrementingAndRearranging(int[] arr){
        Arrays.sort(arr);
        int current=0;
        for(int value:arr)current=Math.min(value,current+1);
        return current;
    }
}

code.kotlin:
class Solution {
    fun maximumElementAfterDecrementingAndRearranging(arr:IntArray):Int{
        arr.sort();
        var current=0;
        for(value in arr)current=minOf(value,current+1);
        return current
    }
}

code.cpp:
class Solution {
    public: int maximumElementAfterDecrementingAndRearranging(vector<int>& arr){
        sort(arr.begin(),arr.end());
        int current=0;
        for(int value:arr)current=min(value,current+1);
        return current;
    }
};
